104 |             <button
105 |               type="button"
106 |               onClick={() => setHealthyView(false)}
107 |               className={cn(
108 |                 'rounded px-2.5 py-1 transition-colors',
109 |                 !healthyView ? 'bg-accent font-medium' : 'text-muted-foreground hover:text-foreground'
110 |               )}
111 |             >
112 |               Live data
113 |             </button>
114 |             <button
115 |               type="button"
116 |               onClick={() => setHealthyView(true)}
