127 | 
128 |       <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
129 |         <Card>
130 |           <CardContent className="p-4">
131 |             <p className="text-[11px] uppercase tracking-wide text-muted-foreground">Databases</p>
132 |             <p className="tnum mt-1 text-2xl font-semibold">{connections.length}</p>
133 |           </CardContent>
134 |         </Card>
135 |         <Card>
136 |           <CardContent className="p-4">
137 |             <p className="text-[11px] uppercase tracking-wide text-muted-foreground">Active problems</p>
138 |             <p className={cn('tnum mt-1 text-2xl font-semibold', totalProblems > 0 && 'text-warning')}>
139 |               {totalProblems}
140 |             </p>
141 |           </CardContent>
142 |         </Card>
143 |         <Card>
144 |           <CardContent className="p-4">
145 |             <p className="text-[11px] uppercase tracking-wide text-muted-foreground">Critical</p>
146 |             <p className={cn('tnum mt-1 text-2xl font-semibold', criticalDbs > 0 && 'text-danger')}>
147 |               {healthyView ? 0 : criticalDbs}
148 |             </p>
149 |           </CardContent>
150 |         </Card>
151 |         <Card>
152 |           <CardContent className="p-4">
153 |             <p className="text-[11px] uppercase tracking-wide text-muted-foreground">Awaiting approval</p>
154 |             <p className="tnum mt-1 text-2xl font-semibold text-info">{awaitingApproval}</p>
155 |           </CardContent>
156 |         </Card>
157 |       </div>
158 | 
159 |       <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
160 |         {connections.map((c) => (
