162 |             key={c.id}
163 |             conn={healthyView ? { ...c, health: 'Healthy', activeProblems: 0 } : c}
164 |             latestDiagnosis={healthyView ? undefined : latestDiagnoses.get(c.id)}
165 |           />
166 |         ))}
167 |       </div>
