chunk_32be977cdbf9f439.numbered_code:
  1 | 'use client';
  2 | 
  3 | import * as React from 'react';
  4 | import { Play } from 'lucide-react';
  5 | import { PageHeader } from '@/components/page-header';
  6 | import { DiagnosisCard } from '@/components/diagnostics/diagnosis-card';
  7 | import { Button } from '@/components/ui/button';
  8 | import { LoadingState, ErrorState, EmptyState } from '@/components/ui/state-feedback';
  9 | import { useToast } from '@/components/app-providers';
 10 | import { useConnectionsQuery } from '@/hooks/use-connections';
 11 | import { useDiagnosticsQuery, useTriggerDiagnosisMutation } from '@/hooks/use-diagnostics';
 12 | import { useAppStore } from '@/stores/use-app-store';
 13 | 
 14 | type Scope = 'this' | 'all';
 15 | type StatusFilter = 'all' | 'Active' | 'Observed' | 'Needs Evidence' | 'Resolved';
 16 | 
 17 | export default function DiagnosticsPage() {
 18 |   const { toast } = useToast();
 19 |   const { data: connections = [] } = useConnectionsQuery();
 20 |   const selectedId = useAppStore((s) => s.selectedConnectionId) || connections[0]?.id;
 21 |   const conn = connections.find((c) => c.id === selectedId);
 22 | 
 23 |   const [scope, setScope] = React.useState<Scope>('this');
 24 |   const [status, setStatus] = React.useState<StatusFilter>('all');
 25 |   const [onlyLow, setOnlyLow] = React.useState(false);
 26 | 
 27 |   const {
 28 |     data: rawDiagnoses = [],
 29 |     isLoading,
 30 |     isError,
 31 |     refetch,
 32 |   } = useDiagnosticsQuery(scope === 'all' ? null : selectedId);
 33 | 
 34 |   const triggerMutation = useTriggerDiagnosisMutation();
 35 | 
 36 |   const list = rawDiagnoses
 37 |     .filter((d) => (status === 'all' ? true : d.status === status))
 38 |     .filter((d) => (onlyLow ? d.lowConfidence : true))
 39 |     .sort((a, b) => Date.parse(b.detectedAtISO) - Date.parse(a.detectedAtISO));
 40 | 
 41 |   const active = rawDiagnoses.filter((d) => d.status === 'Active').length;
 42 | 
 43 |   const handleTrigger = async () => {
 44 |     if (!selectedId) return;
 45 |     try {
 46 |       const res = await triggerMutation.mutateAsync(selectedId);
 47 |       toast({
 48 |         kind: 'info',
 49 |         title: 'Diagnostic Dispatched',
 50 |         description: res.message || 'AI agents are gathering evidence from query plans and lock telemetry.',
 51 |       });
 52 |     } catch (err: unknown) {
 53 |       toast({
 54 |         kind: 'danger',
 55 |         title: 'Trigger Failed',
 56 |         description: err instanceof Error ? err.message : 'Could not dispatch diagnosis.',
 57 |       });
 58 |     }
 59 |   };
 60 | 
 61 |   if (isLoading) {
 62 |     return (
 63 |       <div className="space-y-6">
 64 |         <PageHeader title="Diagnostics" description="Root-cause analyses across monitored databases." />
 65 |         <LoadingState message="Querying agent diagnostic reports and evidence graphs..." />
 66 |       </div>
 67 |     );
 68 |   }
 69 | 
 70 |   if (isError && rawDiagnoses.length === 0) {
 71 |     return (
 72 |       <div className="space-y-6">
 73 |         <PageHeader title="Diagnostics" description="Root-cause analyses across monitored databases." />
 74 |         <ErrorState
 75 |           title="Failed to load diagnostics"
 76 |           message="Could not retrieve diagnostic records from the backend API."
 77 |           onRetry={() => refetch()}
 78 |         />
 79 |       </div>
 80 |     );
 81 |   }
 82 | 
 83 |   return (
 84 |     <div className="space-y-6">
 85 |       <PageHeader
 86 |         title="Diagnostics"
 87 |         description={`Root-cause analyses across ${scope === 'all' ? 'all connected databases' : conn?.name ?? 'this database'}. ${active} active.`}
 88 |         actions={
 89 |           <Button
 90 |             onClick={handleTrigger}
 91 |             disabled={triggerMutation.isPending}
 92 |             className="gap-1.5"
 93 |           >
 94 |             <Play className="h-3.5 w-3.5" />
 95 |             {triggerMutation.isPending ? 'Analyzing Fleet…' : 'Run Diagnostics'}
 96 |           </Button>
 97 |         }
 98 |       />
 99 | 
100 |       <div className="flex flex-wrap items-center gap-2">
101 |         <Segmented
102 |           value={scope}
103 |           onChange={(v) => setScope(v as Scope)}
104 |           options={[
105 |             { value: 'this', label: 'This database' },
106 |             { value: 'all', label: 'All databases' },
107 |           ]}
108 |         />
109 |         <Segmented
110 |           value={status}
111 |           onChange={(v) => setStatus(v as StatusFilter)}
112 |           options={[
113 |             { value: 'all', label: 'All' },
114 |             { value: 'Active', label: 'Active' },
115 |             { value: 'Observed', label: 'Observed' },
116 |             { value: 'Needs Evidence', label: 'Needs evidence' },
117 |             { value: 'Resolved', label: 'Resolved' },
118 |           ]}
119 |         />
120 |         <button
121 |           onClick={() => setOnlyLow((v) => !v)}
122 |           className={`rounded-md border px-2.5 py-1.5 text-xs font-medium transition-colors ${
123 |             onlyLow
124 |               ? 'border-warning/40 bg-warning/10 text-warning'
125 |               : 'border-border text-muted-foreground hover:text-foreground'
126 |           }`}
127 |         >
128 |           Low confidence only
129 |         </button>
130 |       </div>
131 | 
132 |       {list.length === 0 ? (
133 |         <EmptyState
134 |           title="No diagnoses match"
135 |           description="No diagnosis records match this filter. Live snapshots report an observation or insufficient evidence instead of inventing a root cause."
136 |         />
137 |       ) : (
138 |         <div className="grid grid-cols-1 gap-3">
139 |           {list.map((d) => (
140 |               <DiagnosisCard
141 |                 key={d.id}
142 |                 diagnosis={d}
143 |                 showConnection={scope === 'all'}
144 |                 connectionName={connections.find((connection) => connection.id === d.connectionId)?.name}
145 |               />
146 |           ))}
147 |         </div>
148 |       )}
149 |     </div>
150 |   );
151 | }
152 | 
153 | function Segmented({
154 |   value,
155 |   onChange,
156 |   options,
157 | }: {
158 |   value: string;
159 |   onChange: (v: string) => void;
160 |   options: { value: string; label: string }[];
161 | }) {
162 |   return (
163 |     <div className="flex items-center gap-0.5 rounded-md border border-border p-0.5">
164 |       {options.map((o) => (
165 |         <button
166 |           key={o.value}
167 |           onClick={() => onChange(o.value)}
168 |           className={`rounded px-2.5 py-1 text-xs font-medium transition-colors ${
169 |             value === o.value
170 |               ? 'bg-secondary text-secondary-foreground'
171 |               : 'text-muted-foreground hover:text-foreground'
172 |           }`}
173 |         >
174 |           {o.label}
175 |         </button>
176 |       ))}
177 |     </div>
178 |   );
179 | }

