 34 | 
 35 |   if (isLoading) {
 36 |     return (
 37 |       <div className="space-y-6">
 38 |         <PageHeader title="Experiment detail" />
 39 |         <LoadingState message="Loading statistical verification and policy verdict..." />
 40 |       </div>
 41 |     );
 42 |   }
 43 | 
 44 |   if (isError || !exp) {
 45 |     return (
 46 |       <div className="space-y-6">
 47 |         <PageHeader title="Experiment not found" />
