 54 |             </Button>
 55 |           }
 56 |         />
 57 |       </div>
 58 |     );
 59 |   }
 60 | 
 61 |   const completed = exp.outcome === 'COMMIT' || exp.outcome === 'ROLLBACK';
 62 |   const canaryRunning = exp.approvalState === 'APPROVED' && exp.outcome === 'IN_PROGRESS';
 63 |   const awaitingApproval =
 64 |     exp.approvalState === 'PENDING_APPROVAL' && exp.outcome === 'AWAITING_APPROVAL';
 65 | 
 66 |   async function handleApprove() {
 67 |     if (!exp) return;
 68 |     try {
 69 |       await approveMutation.mutateAsync({ id: exp.id, notes: 'Approved by Lead DBA' });
 70 |       toast({
 71 |         kind: 'success',
 72 |         title: 'Approval recorded',
 73 |         description: 'Canary deployment started. The audit trail has been updated.',
 74 |       });
 75 |     } catch (err: unknown) {
 76 |       toast({
 77 |         kind: 'danger',
 78 |         title: 'Approval failed',
 79 |         description: err instanceof Error ? err.message : 'Could not record approval.',
 80 |       });
 81 |     }
 82 |   }
 83 | 
 84 |   async function handleReject() {
 85 |     if (!exp) return;
 86 |     try {
 87 |       await rejectMutation.mutateAsync({ id: exp.id, reason: 'Rejected by operator' });
 88 |       toast({
 89 |         kind: 'warning',
 90 |         title: 'Experiment rejected',
 91 |         description: 'No deployment will proceed. The candidate optimization has been marked rejected.',
 92 |       });
 93 |     } catch (err: unknown) {
 94 |       toast({
 95 |         kind: 'danger',
 96 |         title: 'Rejection failed',
 97 |         description: err instanceof Error ? err.message : 'Could not record rejection.',
 98 |       });
 99 |     }
100 |   }
101 | 
102 |   return (
