105 |         breadcrumb={
106 |           <Link href="/experiments" className="inline-flex items-center gap-1 hover:text-foreground">
107 |             <ArrowLeft className="h-3 w-3" /> Optimization history
108 |           </Link>
109 |         }
110 |         title={`Experiment ${exp.id}`}
111 |         description={`Candidate optimization verification for ${conn?.name || exp.connectionId}.`}
112 |       />
113 | 
114 |       <div className="flex flex-wrap items-center gap-2">
115 |         <StatusBadge status={exp.verdict} dot />
116 |         <StatusBadge status={exp.outcome} />
117 |         <span className="text-xs text-muted-foreground">
