135 |           outcome={exp.outcome === 'COMMIT' || exp.outcome === 'ROLLBACK' ? exp.outcome : 'COMMIT'}
136 |           rollbackReason={exp.rollbackReason}
137 |         />
138 |       )}
139 | 
140 |       <Card>
141 |         <CardHeader>
142 |           <CardTitle>Baseline vs Candidate Benchmark</CardTitle>
143 |           <CardDescription>
144 |             Bootstrap confidence intervals (N=10,000 resamples). Significance: {exp.significance}
145 |           </CardDescription>
146 |         </CardHeader>
147 |         <CardContent>
148 |           <div className="overflow-x-auto">
149 |             <table className="w-full text-xs">
150 |               <thead>
151 |                 <tr className="border-b border-border text-muted-foreground">
152 |                   <th className="pb-2 text-left font-medium">Metric</th>
153 |                   <th className="pb-2 text-right font-medium">Baseline</th>
154 |                   <th className="pb-2 text-right font-medium">Candidate</th>
155 |                   <th className="pb-2 text-right font-medium">Delta</th>
156 |                 </tr>
157 |               </thead>
158 |               <tbody className="divide-y divide-border/40">
159 |                 {exp.comparisons.map((c) => {
