 91 | function LiveMetrics({ conn }: { conn: DatabaseConnection }) {
 92 |   const isLive = useAppStore((s) => s.isLiveMode);
 93 |   const setIsLive = useAppStore((s) => s.setIsLiveMode);
 94 |   const pollingIntervalMs = useAppStore((s) => s.pollingIntervalMs);
 95 |   const setPollingIntervalMs = useAppStore((s) => s.setPollingIntervalMs);
 96 |   const { data: snapshot, isError, error } = useLiveMetricsQuery(conn.id);
 97 | 
 98 |   if (isError) {
 99 |     return (
100 |       <EmptyState
101 |         title="Could not read live telemetry"
102 |         description={error instanceof Error ? error.message : 'The selected database telemetry request failed.'}
103 |       />
104 |     );
105 |   }
106 | 
107 |   if (!snapshot) return <LoadingState message="Reading live PostgreSQL telemetry..." />;
108 | 
109 |   const hasTelemetry =
110 |     snapshot.query_telemetry_available ||
111 |     snapshot.table_telemetry_available ||
112 |     snapshot.top_queries.length > 0 ||
113 |     snapshot.active_tables_count > 0;
114 |   const pointTime = Date.parse(snapshot.window_end);
115 |   const point = (value: number | null | undefined) =>
116 |     value == null || Number.isNaN(pointTime) ? [] : [{ t: pointTime, value }];
117 |   const series = {
118 |     avg: point(snapshot.avg_latency_ms),
119 |     slowest: point(snapshot.p95_latency_ms),
120 |     cache: point(snapshot.cache_hit_ratio == null ? null : snapshot.cache_hit_ratio * 100),
121 |     queries: point(snapshot.total_queries),
122 |     tables: point(snapshot.active_tables_count),
123 |   };
124 |   const metricCards: Array<{
125 |     key: keyof typeof series;
126 |     label: string;
127 |     unit: string;
128 |     value: number;
129 |     tone: 'primary' | 'danger' | 'success' | 'info' | 'warning';
130 |   }> = [
131 |     { key: 'avg' as const, label: 'Average latency', unit: 'ms', value: snapshot.avg_latency_ms, tone: 'primary' as const },
132 |     { key: 'slowest' as const, label: 'Highest observed latency', unit: 'ms', value: snapshot.p95_latency_ms, tone: 'danger' as const },
133 |     ...(snapshot.cache_hit_ratio == null
134 |       ? []
135 |       : [{ key: 'cache' as const, label: 'Cache hit ratio', unit: '%', value: snapshot.cache_hit_ratio * 100, tone: 'success' as const }]),
136 |     { key: 'queries' as const, label: 'Statement calls', unit: '', value: snapshot.total_queries, tone: 'info' as const },
137 |     { key: 'tables' as const, label: 'Active tables', unit: '', value: snapshot.active_tables_count, tone: 'warning' as const },
138 |   ];
139 | 
140 |   return (
141 |     <div className="space-y-6">
142 |       <PageHeader
143 |         title="Live monitoring"
144 |         description={`Live signal from ${conn.name}. Values come directly from PostgreSQL system views and refresh every ${pollingIntervalMs / 1000}s.`}
145 |         actions={
146 |           <div className="flex flex-wrap items-center gap-2">
147 |             <select
148 |               value={pollingIntervalMs}
149 |               onChange={(e) => setPollingIntervalMs(Number(e.target.value))}
150 |               className="h-8 rounded-md border border-border bg-background px-2 text-xs font-medium outline-none"
151 |             >
152 |               <option value={2000}>Poll: 2s</option>
153 |               <option value={5000}>Poll: 5s</option>
154 |               <option value={10000}>Poll: 10s</option>
155 |             </select>
156 | 
157 |             <Button
158 |               variant="outline"
159 |               size="sm"
160 |               onClick={() => setIsLive(!isLive)}
161 |               className="gap-1.5"
162 |             >
163 |               {isLive ? <Pause className="h-3.5 w-3.5" /> : <Play className="h-3.5 w-3.5" />}
164 |               {isLive ? 'Pause' : 'Resume'}
165 |             </Button>
166 |           </div>
167 |         }
168 |       />
169 | 
170 |       <div className="flex flex-wrap items-center gap-3">
171 |         <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
172 |           <span
173 |             className={`h-2 w-2 rounded-full ${isLive ? 'animate-pulse bg-success' : 'bg-muted-foreground'}`}
174 |           />
175 |           {isLive ? 'Live Streaming' : 'Polling Paused'}
176 |         </span>
177 |         <StatusBadge status={conn.health} dot />
178 |         <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
179 |           <Activity className="h-3.5 w-3.5" />
180 |           {conn.provider}{conn.region ? ` · ${conn.region}` : ''}{conn.version ? ` · ${conn.version}` : ''}
181 |         </span>
182 |         <span className="text-xs text-muted-foreground">
183 |           Query stats: {snapshot.query_telemetry_available ? 'available' : 'unavailable'}
184 |         </span>
185 |       </div>
186 | 
187 |       {hasTelemetry ? (
188 |         <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
189 |           {metricCards.map((metric) => (
190 |             <MetricChart
191 |               key={metric.key}
192 |               label={metric.label}
193 |               unit={metric.unit}
194 |               data={series[metric.key] ?? []}
195 |               current={metric.value}
196 |               tone={metric.tone}
197 |               format={metric.unit === '' ? (n) => Math.round(n).toLocaleString() : undefined}
198 |             />
199 |           ))}
200 |         </div>
201 |       ) : (
202 |         <EmptyState
203 |           title="No telemetry available yet"
204 |           description="The connection is valid, but PostgreSQL has not returned query or table statistics for this snapshot."
205 |         />
206 |       )}
207 | 
208 |       <SlowQueryTable
209 |         realQueries={snapshot?.top_queries}
210 |       />
211 |     </div>
212 |   );
213 | }

