 45 | 
 46 |   if (!open) return null;
 47 | 
 48 |   function buildPayload(): CreateConnectionPayload {
 49 |     if (mode === 'string') {
 50 |       if (!connectionString.trim()) throw new Error('Enter a PostgreSQL connection string.');
 51 | 
 52 |       let parsed: URL;
 53 |       try {
 54 |         parsed = new URL(connectionString.trim());
 55 |       } catch {
 56 |         throw new Error('Enter a valid PostgreSQL connection string.');
 57 |       }
 58 | 
 59 |       const databaseName = decodeURIComponent(parsed.pathname.replace(/^\//, ''));
 60 |       if (!parsed.hostname || !databaseName || !parsed.username) {
 61 |         throw new Error('The connection string must include host, database, and username.');
 62 |       }
 63 | 
 64 |       return {
 65 |         name: fields.name.trim() || databaseName,
 66 |         provider: 'postgresql',
 67 |         host: parsed.hostname,
 68 |         port: Number(parsed.port || 5432),
 69 |         database_name: databaseName,
 70 |         username: decodeURIComponent(parsed.username),
 71 |         password: parsed.password ? decodeURIComponent(parsed.password) : undefined,
 72 |         ssl_mode: parsed.searchParams.get('sslmode') || 'require',
 73 |         connection_string: connectionString.trim(),
 74 |       };
 75 |     }
 76 | 
 77 |     if (!fields.name.trim() || !fields.host.trim() || !fields.database.trim() || !fields.username.trim()) {
 78 |       throw new Error('Name, host, database, and username are required.');
 79 |     }
 80 | 
 81 |     return {
 82 |       name: fields.name.trim(),
 83 |       provider: 'postgresql',
 84 |       host: fields.host.trim(),
 85 |       port: fields.port,
 86 |       database_name: fields.database.trim(),
 87 |       username: fields.username.trim(),
 88 |       password: fields.password || undefined,
 89 |       ssl_mode: fields.ssl ? 'require' : 'prefer',
 90 |     };
 91 |   }
