 93 |   async function runTestAndSave() {
 94 |     setTesting(true);
 95 |     setStates(Object.fromEntries(STEPS.map((step) => [step.key, 'running'])));
 96 | 
 97 |     try {
 98 |       const payload = buildPayload();
 99 |       const result = await testMutation.mutateAsync(payload);
100 |       const nextStates: Record<string, StepState> = {
101 |         reach: result.reachability ? 'pass' : 'fail',
102 |         creds: result.credentials ? 'pass' : 'fail',
103 |         ext: result.pgStatStatements ? 'pass' : 'fail',
104 |         perms: result.readOnlyRole ? 'pass' : 'fail',
105 |       };
106 |       setStates(nextStates);
107 | 
