 6 | 
 7 | function Counter({ value, prefix = "", suffix = "" }: { value: number; prefix?: string; suffix?: string }) {
 8 |   const ref = useRef<HTMLSpanElement>(null);
 9 |   const inView = useInView(ref, { once: true, margin: "-60px" });
10 |   const [n, setN] = useState(0);
11 | 
12 |   useEffect(() => {
13 |     if (!inView) return;
14 |     let raf = 0;
15 |     const start = performance.now();
16 |     const tick = (t: number) => {
17 |       const p = Math.min((t - start) / 1400, 1);
18 |       setN(Math.round(value * (1 - Math.pow(1 - p, 3))));
19 |       if (p < 1) raf = requestAnimationFrame(tick);
20 |     };
21 |     raf = requestAnimationFrame(tick);
22 |     return () => cancelAnimationFrame(raf);
23 |   }, [inView, value]);
24 | 
25 |   return (
26 |     <span ref={ref} className="font-display text-4xl font-semibold tracking-tight sm:text-5xl">
27 |       {prefix}
28 |       {n.toLocaleString()}
29 |       {suffix}
30 |     </span>
31 |   );
