 3 | import * as React from 'react'
 4 | import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
 5 | 
 6 | function makeQueryClient() {
 7 |   return new QueryClient({
 8 |     defaultOptions: {
 9 |       queries: {
10 |         staleTime: 10 * 1000,
11 |         refetchOnWindowFocus: false,
12 |         retry: 1,
13 |       },
14 |     },
15 |   })
16 | }
17 | 
18 | let browserQueryClient: QueryClient | undefined = undefined
19 | 
20 | function getQueryClient() {
21 |   if (typeof window === 'undefined') {
22 |     // Server: always make a new query client
23 |     return makeQueryClient()
24 |   } else {
25 |     // Browser: make a new query client if we don't already have one
26 |     if (!browserQueryClient) browserQueryClient = makeQueryClient()
27 |     return browserQueryClient
28 |   }
29 | }
30 | 
31 | export function QueryProvider({ children }: { children: React.ReactNode }) {
32 |   const queryClient = getQueryClient()
33 | 
34 |   return (
35 |     <QueryClientProvider client={queryClient}>
36 |       {children}
37 |     </QueryClientProvider>
38 |   )
39 | }

