chunk_40b0788672cb92a5.numbered_code:
 1 | import { apiClient } from './client';
 2 | import type { ActivityItem } from '../../types/types';
 3 | 
 4 | interface BackendAuditLog {
 5 |   id: string;
 6 |   user_id?: string | null;
 7 |   connection_id?: string | null;
 8 |   action_type: string;
 9 |   target_entity: string;
10 |   target_id?: string | null;
11 |   details?: Record<string, unknown> | null;
12 |   timestamp: string;
13 | }
14 | 
15 | interface BackendAuditResponse {
16 |   total: number;
17 |   items: BackendAuditLog[];
18 | }
19 | 
20 | function mapActionKind(actionType: string): ActivityItem['kind'] {
21 |   const norm = actionType.toUpperCase();
22 |   if (norm.includes('ROLLBACK')) return 'rollback';
23 |   if (norm.includes('COMMIT') || norm.includes('APPLIED') || norm.includes('CANARY_SUCCESS')) return 'commit';
24 |   if (norm.includes('APPROV')) return 'approve';
25 |   if (norm.includes('FORECAST')) return 'forecast';
26 |   return 'diagnose';
27 | }
28 | 
29 | function formatAuditMessage(log: BackendAuditLog): string {
30 |   const details = log.details || {};
31 |   if (log.action_type === 'DIAGNOSIS_GENERATED') {
32 |     const cause = details.primary_root_cause ? String(details.primary_root_cause) : 'issues';
33 |     return `Root cause analysis completed: ${cause} detected.`;
34 |   }
35 |   if (log.action_type === 'CANARY_START') {
36 |     return 'Guarded canary deployment started on live database.';
37 |   }
38 |   if (log.action_type === 'CANARY_COMMIT') {
39 |     return 'Canary verification succeeded; changes committed.';
40 |   }
41 |   if (log.action_type === 'CANARY_ROLLBACK') {
42 |     return 'Canary regression threshold breached; automated rollback executed.';
43 |   }
44 |   if (log.action_type === 'RECOMMENDATION_APPROVED') {
45 |     return 'Candidate optimization approved for canary deployment.';
46 |   }
47 |   return `${log.action_type.replace(/_/g, ' ').toLowerCase()} on ${log.target_entity}.`;
48 | }
49 | 
50 | export const auditApi = {
51 |   list: async (limit = 20): Promise<ActivityItem[]> => {
52 |     try {
53 |       const data = await apiClient.get<BackendAuditResponse | BackendAuditLog[]>(`/audit/logs?limit=${limit}`);
54 |       const logs = Array.isArray(data) ? data : (data?.items || []);
55 |       return logs.map((log) => ({
56 |         id: log.id,
57 |         timeISO: log.timestamp || new Date().toISOString(),
58 |         connectionId: log.connection_id || 'system',
59 |         message: formatAuditMessage(log),
60 |         kind: mapActionKind(log.action_type),
61 |       }));
62 |     } catch (err) {
63 |       console.warn('[auditApi.list] Failed to fetch live audit logs:', err);
64 |       return [];
65 |     }
66 |   },
67 | };
68 |

