chunk_309a9481e82d382e.numbered_code:
  1 | /**
  2 |  * Universal HTTP Client for Zentrix.ai Frontend.
  3 |  * Uses NEXT_PUBLIC_API_URL environment variable and attaches Clerk session tokens.
  4 |  */
  5 | 
  6 | const configuredApiUrl =
  7 |   process.env.NEXT_PUBLIC_API_BASE_URL || process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
  8 | 
  9 | export const API_BASE_URL = configuredApiUrl.replace(/\/$/, '').endsWith('/api/v1')
 10 |   ? configuredApiUrl.replace(/\/$/, '')
 11 |   : `${configuredApiUrl.replace(/\/$/, '')}/api/v1`;
 12 | 
 13 | export interface ApiErrorResponse {
 14 |   detail?: string | { message?: string; msg?: string }[] | Record<string, unknown>;
 15 |   message?: string;
 16 |   status?: number;
 17 | }
 18 | 
 19 | export class ApiError extends Error {
 20 |   status: number;
 21 |   data?: unknown;
 22 | 
 23 |   constructor(message: string, status: number, data?: unknown) {
 24 |     super(message);
 25 |     this.name = 'ApiError';
 26 |     this.status = status;
 27 |     this.data = data;
 28 |   }
 29 | }
 30 | 
 31 | interface RequestOptions extends RequestInit {
 32 |   params?: Record<string, string | number | boolean | undefined | null>;
 33 | }
 34 | 
 35 | export type AuthTokenGetter = () => Promise<string | null> | string | null;
 36 | 
 37 | let globalAuthTokenGetter: AuthTokenGetter | null = null;
 38 | 
 39 | export function setApiAuthTokenGetter(getter: AuthTokenGetter | null) {
 40 |   globalAuthTokenGetter = getter;
 41 | }
 42 | 
 43 | export async function request<T>(endpoint: string, options: RequestOptions = {}): Promise<T> {
 44 |   const { params, headers, ...customConfig } = options;
 45 | 
 46 |   let url = endpoint.startsWith('http')
 47 |     ? endpoint
 48 |     : `${API_BASE_URL}${endpoint.startsWith('/') ? endpoint : `/${endpoint}`}`;
 49 | 
 50 |   if (params) {
 51 |     const searchParams = new URLSearchParams();
 52 |     Object.entries(params).forEach(([key, value]) => {
 53 |       if (value !== undefined && value !== null) {
 54 |         searchParams.append(key, String(value));
 55 |       }
 56 |     });
 57 |     const queryString = searchParams.toString();
 58 |     if (queryString) {
 59 |       url += (url.includes('?') ? '&' : '?') + queryString;
 60 |     }
 61 |   }
 62 | 
 63 |   const defaultHeaders: Record<string, string> = {
 64 |     'Content-Type': 'application/json',
 65 |   };
 66 | 
 67 |   // Retrieve token dynamically from Clerk Auth bridge or fallback
 68 |   let token: string | null = null;
 69 | 
 70 |   if (globalAuthTokenGetter) {
 71 |     try {
 72 |       token = await globalAuthTokenGetter();
 73 |     } catch (err) {
 74 |       console.warn('[apiClient] Error retrieving session token from auth getter:', err);
 75 |     }
 76 |   }
 77 | 
 78 |   if (!token && typeof window !== 'undefined') {
 79 |     const clerk = (window as unknown as { Clerk?: { session?: { getToken: () => Promise<string | null> } } }).Clerk;
 80 |     if (clerk?.session) {
 81 |       try {
 82 |         token = await clerk.session.getToken();
 83 |       } catch {
 84 |         // Continue to fallback
 85 |       }
 86 |     }
 87 |     if (!token) {
 88 |       token = localStorage.getItem('zentrix_auth_token');
 89 |     }
 90 |   }
 91 | 
 92 |   if (token) {
 93 |     defaultHeaders['Authorization'] = `Bearer ${token}`;
 94 |   }
 95 | 
 96 |   const config: RequestInit = {
 97 |     method: 'GET',
 98 |     credentials: 'include',
 99 |     headers: {
100 |       ...defaultHeaders,
101 |       ...headers,
102 |     },
103 |     ...customConfig,
104 |   };
105 | 
106 |   try {
107 |     const response = await fetch(url, config);
108 | 
109 |     if (!response.ok) {
110 |       let errorData: ApiErrorResponse | null = null;
111 |       try {
112 |         errorData = await response.json();
113 |       } catch {
114 |         // Not JSON
115 |       }
116 | 
117 |       let message = `API error ${response.status}: ${response.statusText}`;
118 |       if (errorData?.detail) {
119 |         if (typeof errorData.detail === 'string') {
120 |           message = errorData.detail;
121 |         } else if (Array.isArray(errorData.detail)) {
122 |           message = errorData.detail
123 |             .map((e: unknown) => {
124 |               if (typeof e === 'object' && e !== null) {
125 |                 const item = e as Record<string, unknown>;
126 |                 return String(item.msg || item.message || JSON.stringify(e));
127 |               }
128 |               return String(e);
129 |             })
130 |             .join(', ');
131 |         }
132 |       } else if (errorData?.message) {
133 |         message = errorData.message;
134 |       }
135 | 
136 |       throw new ApiError(message, response.status, errorData);
137 |     }
138 | 
139 |     if (response.status === 204) {
140 |       return {} as T;
141 |     }
142 | 
143 |     return (await response.json()) as T;
144 |   } catch (err: unknown) {
145 |     if (err instanceof ApiError) {
146 |       throw err;
147 |     }
148 |     const message = err instanceof Error ? err.message : 'Network error';
149 |     throw new ApiError(message, 0, err);
150 |   }
151 | }
152 | 
153 | export const apiClient = {
154 |   get: <T>(endpoint: string, options?: RequestOptions) =>
155 |     request<T>(endpoint, { method: 'GET', ...options }),
156 | 
157 |   post: <T>(endpoint: string, body?: unknown, options?: RequestOptions) =>
158 |     request<T>(endpoint, {
159 |       method: 'POST',
160 |       body: body !== undefined ? JSON.stringify(body) : undefined,
161 |       ...options,
162 |     }),
163 | 
164 |   put: <T>(endpoint: string, body?: unknown, options?: RequestOptions) =>
165 |     request<T>(endpoint, {
166 |       method: 'PUT',
167 |       body: body !== undefined ? JSON.stringify(body) : undefined,
168 |       ...options,
169 |     }),
170 | 
171 |   patch: <T>(endpoint: string, body?: unknown, options?: RequestOptions) =>
172 |     request<T>(endpoint, {
173 |       method: 'PATCH',
174 |       body: body !== undefined ? JSON.stringify(body) : undefined,
175 |       ...options,
176 |     }),
177 | 
178 |   delete: <T>(endpoint: string, options?: RequestOptions) =>
179 |     request<T>(endpoint, { method: 'DELETE', ...options }),
