  1 | import { apiClient } from './client';
  2 | import type {
  3 |   ContributingCause,
  4 |   Diagnosis,
  5 |   EvidenceEdge,
  6 |   EvidenceNode,
  7 |   Recommendation,
  8 |   SupportingEvidence,
  9 |   TimelineEntry,
 10 | } from '../../types/types';
 11 | 
 12 | interface BackendEvidenceNode {
 13 |   id: string;
 14 |   node_type: string;
 15 |   label: string;
