 30 | interface BackendDiagnosis {
 31 |   id: string;
 32 |   connection_id: string;
 33 |   title: string;
 34 |   primary_root_cause: string;
 35 |   contributing_factors?: Array<Record<string, unknown>> | null;
 36 |   severity: string;
 37 |   confidence: number;
 38 |   summary: string;
 39 |   validation_plan?: Record<string, unknown> | null;
 40 |   status: string;
 41 |   created_at: string;
 42 |   updated_at: string;
 43 |   evidence_graph?: {
 44 |     nodes: BackendEvidenceNode[];
 45 |     edges: BackendEvidenceEdge[];
 46 |   };
