 48 | 
 49 | interface BackendRecommendation {
 50 |   id: string;
 51 |   diagnosis_id: string;
 52 |   connection_id: string;
 53 |   diagnosis_title: string;
 54 |   primary_root_cause: string;
 55 |   type: Recommendation['type'];
 56 |   title: string;
 57 |   rationale: string;
 58 |   predicted_impact: string;
 59 |   uncertainty_pct: number;
 60 |   risk: Recommendation['risk'];
 61 |   candidate_sql: string;
 62 |   experiment_id?: string | null;
 63 | }
 64 | 
 65 | function text(value: unknown, fallback: string): string {
 66 |   if (value == null) return fallback;
 67 |   if (typeof value === 'string') return value;
 68 |   try {
 69 |     return JSON.stringify(value);
 70 |   } catch {
 71 |     return fallback;
 72 |   }
 73 | }
 74 | 
 75 | function toNode(node: BackendEvidenceNode): EvidenceNode {
 76 |   const metadata = node.metadata_payload || {};
 77 |   const normalizedType = node.node_type.toLowerCase();
 78 |   return {
 79 |     id: node.id,
 80 |     kind: normalizedType.includes('root') || normalizedType.includes('hypothesis') ? 'cause' : normalizedType === 'metric' ? 'symptom' : 'event',
 81 |     label: node.label,
 82 |     detail: text(metadata.detail || metadata.claim || metadata.evidence, `${node.agent_domain} evidence`),
 83 |     metric: metadata.metric ? String(metadata.metric) : undefined,
 84 |     value: metadata.value != null ? String(metadata.value) : undefined,
 85 |   };
 86 | }
 87 | 
 88 | function toTimeline(value: unknown): TimelineEntry[] {
 89 |   if (!Array.isArray(value)) return [];
 90 |   return value.flatMap((entry) => {
 91 |     if (!entry || typeof entry !== 'object') return [];
 92 |     const item = entry as Record<string, unknown>;
 93 |     const event = String(item.event || 'evidence');
 94 |     const icon: TimelineEntry['icon'] = event.includes('lock')
 95 |       ? 'lock'
 96 |       : event.includes('query')
 97 |         ? 'latency'
 98 |         : event.includes('plan')
 99 |           ? 'plan'
100 |           : 'stats';
101 |     return [{
102 |       timeISO: text(item.timestamp, new Date().toISOString()),
103 |       title: event.replaceAll('_', ' '),
104 |       detail: item.latency_ms != null ? `Observed latency: ${item.latency_ms} ms.` : 'Captured from the live PostgreSQL target.',
105 |       icon,
106 |     } satisfies TimelineEntry];
107 |   });
108 | }
109 | 
110 | function toDiagnosis(data: BackendDiagnosis): Diagnosis {
111 |   const graph = data.evidence_graph || { nodes: [], edges: [] };
112 |   const validation = data.validation_plan || {};
113 |   const rootCause = data.primary_root_cause.toUpperCase() as Diagnosis['primaryRootCause'];
114 |   const contributingCauses: ContributingCause[] = (data.contributing_factors || []).map((item, index) => ({
115 |     rootCause: text(item.cause || item.rootCause, 'UNKNOWN') as Diagnosis['primaryRootCause'],
116 |     rank: index === 0 ? 'CONTRIBUTING' : 'CORRELATED',
117 |     confidencePct: Math.round(Number(item.confidence || 0) * 100),
118 |     summary: text(item.summary || item.agent, 'Observed supporting evidence from the live database.'),
119 |   }));
120 |   const modelOutputs = validation.model_outputs;
121 |   const recommendations: Recommendation[] = [];
122 |   const supportingEvidence: SupportingEvidence[] = Array.isArray(validation.supporting_evidence)
123 |     ? validation.supporting_evidence.map((item, index) => {
124 |         const evidence: Record<string, unknown> =
125 |           typeof item === 'object' && item !== null ? (item as Record<string, unknown>) : { claim: item };
126 |         return {
127 |           id: `${data.id}-evidence-${index}`,
128 |           claim: text(evidence.claim || evidence.metric, 'Live PostgreSQL evidence'),
129 |           metric: text(evidence.metric, 'observed metric'),
130 |           value: text(evidence.value, 'observed'),
131 |           rank: index === 0 ? 'PRIMARY' : 'CONTRIBUTING',
132 |         };
133 |       })
134 |     : [];
135 | 
136 |   return {
137 |     id: data.id,
138 |     connectionId: data.connection_id,
139 |     title: data.title,
140 |     primaryRootCause: rootCause,
141 |     confidencePct: Math.round(Number(data.confidence || 0) * 100),
142 |     status: data.status === 'RESOLVED'
143 |       ? 'Resolved'
144 |       : data.status === 'OBSERVED'
145 |         ? 'Observed'
146 |         : data.status === 'INSUFFICIENT_EVIDENCE'
147 |           ? 'Needs Evidence'
148 |           : 'Active',
149 |     detectedAtISO: data.created_at,
150 |     lowConfidence: Number(data.confidence || 0) < 0.5,
151 |     summary: data.summary,
152 |     affectedObject: text(validation.affected_object, 'database'),
153 |     telemetrySource: validation.source ? String(validation.source) : undefined,
154 |     capturedAtISO: validation.captured_at ? String(validation.captured_at) : undefined,
155 |     telemetryWarnings: [
156 |       ...(Array.isArray(validation.capture_errors)
157 |         ? validation.capture_errors.map((item) => `Telemetry source unavailable: ${text((item as Record<string, unknown>).source, 'unknown')}`)
158 |         : []),
159 |       ...(Array.isArray(validation.plan_errors)
160 |         ? validation.plan_errors.map(() => 'Some query plans could not be captured from the monitored database.')
161 |         : []),
162 |     ],
163 |     modelResults:
164 |       modelOutputs && typeof modelOutputs === 'object'
165 |         ? (modelOutputs as Diagnosis['modelResults'])
166 |         : undefined,
167 |     contributingCauses,
168 |     evidenceNodes: graph.nodes.map(toNode),
169 |     evidenceEdges: graph.edges.map((edge): EvidenceEdge => ({ from: edge.source_node_id, to: edge.target_node_id })),
170 |     timeline: toTimeline(validation.timeline),
171 |     supportingEvidence,
172 |     recommendations,
173 |   };
174 | }
175 | 
