  1 | import { apiClient } from './client';
  2 | import type { Experiment, Recommendation } from '../../types/types';
  3 | 
  4 | interface BackendExperiment {
  5 |   id: string;
  6 |   connection_id: string;
  7 |   diagnosis_id?: string | null;
  8 |   strategy: string;
  9 |   candidate_sql: string;
 10 |   baseline_latency: number;
 11 |   baseline_p95: number;
 12 |   baseline_cpu: number;
 13 |   baseline_io: number;
 14 |   candidate_latency: number;
 15 |   candidate_p95: number;
 16 |   candidate_cpu: number;
 17 |   candidate_io: number;
 18 |   predicted_latency_delta: number;
 19 |   actual_latency_delta?: number | null;
 20 |   statistical_significance: boolean;
 21 |   confidence_interval_low?: number | null;
 22 |   confidence_interval_high?: number | null;
 23 |   skeptic_findings?: Record<string, unknown> | null;
 24 |   policy_verdict: string;
 25 |   success: boolean;
 26 |   risk: string;
 27 |   rollback: boolean;
 28 |   status: string;
 29 |   created_at: string;
 30 |   updated_at: string;
 31 | }
 32 | 
 33 | function strategyType(strategy: string): Recommendation['type'] {
 34 |   if (strategy.includes('INDEX')) return 'INDEX';
 35 |   if (strategy.includes('ANALYZE') || strategy.includes('STATISTICS')) return 'STATISTICS';
 36 |   if (strategy.includes('VACUUM')) return 'VACUUM';
 37 |   if (strategy.includes('CONFIG')) return 'CONFIG';
 38 |   return 'QUERY_REWRITE';
 39 | }
 40 | 
 41 | function toExperiment(data: BackendExperiment): Experiment {
 42 |   const findings = data.skeptic_findings || {};
 43 |   const verification = (findings.verification || {}) as Record<string, unknown>;
 44 |   const policy = (findings.policy || {}) as Record<string, unknown>;
 45 |   const riskFactors = (findings.risk_factors as string[] | undefined) || [];
 46 |   const verdict = (data.policy_verdict === 'APPROVE' ? 'VERIFIED' : data.policy_verdict) as Experiment['verdict'];
 47 |   const outcome: Experiment['outcome'] = data.status === 'ROLLED_BACK' || data.rollback
 48 |     ? 'ROLLBACK'
 49 |     : data.status === 'DEPLOYED'
 50 |       ? 'IN_PROGRESS'
 51 |       : data.status === 'APPROVED'
 52 |         ? 'IN_PROGRESS'
 53 |         : verdict === 'REJECTED'
 54 |           ? 'ROLLBACK'
 55 |           : 'AWAITING_APPROVAL';
 56 |   const currentStage = data.status === 'PENDING'
 57 |     ? 'HypoPG filter'
 58 |     : data.status === 'SIMULATED'
 59 |       ? 'Policy engine'
 60 |       : data.status === 'APPROVED' || data.status === 'DEPLOYED'
 61 |         ? 'Policy engine'
 62 |         : 'Policy engine';
 63 | 
 64 |   return {
 65 |     id: data.id,
 66 |     connectionId: data.connection_id,
 67 |     diagnosisId: data.diagnosis_id || undefined,
 68 |     candidate: data.candidate_sql,
 69 |     recommendationType: strategyType(data.strategy),
 70 |     verdict,
 71 |     outcome,
 72 |     approvalState: verdict === 'REJECTED' || data.status === 'REJECTED' || data.status === 'ROLLED_BACK'
 73 |       ? 'REJECTED'
 74 |       : data.status === 'APPROVED' || data.status === 'DEPLOYED'
 75 |       ? 'APPROVED'
 76 |       : 'PENDING_APPROVAL',
 77 |     createdAtISO: data.created_at,
 78 |     currentStage,
 79 |     comparisons: [
 80 |       { metric: 'Mean latency', unit: 'ms', baseline: data.baseline_latency, candidate: data.candidate_latency, betterWhenLower: true },
 81 |       { metric: 'P95 latency', unit: 'ms', baseline: data.baseline_p95, candidate: data.candidate_p95, betterWhenLower: true },
 82 |       { metric: 'CPU', unit: '', baseline: data.baseline_cpu, candidate: data.candidate_cpu, betterWhenLower: true },
 83 |       { metric: 'IO', unit: '', baseline: data.baseline_io, candidate: data.candidate_io, betterWhenLower: true },
 84 |     ],
 85 |     regressionRatePct: Number(verification.regression_rate || 0) * 100,
 86 |     ciLow: Number(data.confidence_interval_low || 0),
 87 |     ciHigh: Number(data.confidence_interval_high || 0),
 88 |     significance: data.statistical_significance ? 'SIGNIFICANT' : 'NOT_SIGNIFICANT',
 89 |     skepticFindings: riskFactors.map((concern) => ({
 90 |       concern,
 91 |       status: 'flagged' as const,
 92 |       note: 'Reported by the Skeptic Agent from the shadow replay.',
 93 |     })),
 94 |     policyChecks: [
 95 |       ...((policy.passed_rules as string[] | undefined) || []).map((rule) => ({ rule, passed: true })),
 96 |       ...((policy.violated_rules as string[] | undefined) || []).map((rule) => ({ rule, passed: false })),
 97 |     ],
 98 |     auditLog: [],
 99 |   };
100 | }
101 | 
102 | export const experimentsApi = {
103 |   list: async (): Promise<Experiment[]> => {
104 |     const data = await apiClient.get<BackendExperiment[]>('/experiments');
105 |     return data.map(toExperiment);
106 |   },
107 | 
108 |   getById: async (id: string): Promise<Experiment> => {
109 |     const data = await apiClient.get<BackendExperiment>(`/experiments/${id}`);
110 |     return toExperiment(data);
111 |   },
112 | 
113 |   simulate: async (recommendation: Recommendation): Promise<Experiment> => {
114 |     if (!recommendation.connectionId || !recommendation.diagnosisId || !recommendation.candidateSql) {
115 |       throw new Error('Recommendation is missing its database, diagnosis, or candidate SQL');
116 |     }
117 |     const data = await apiClient.post<BackendExperiment>(`/recommendations/${recommendation.id}/simulate`, {
118 |       strategy: recommendation.type === 'INDEX' ? 'CREATE_INDEX' : recommendation.type,
119 |       candidate_sql: recommendation.candidateSql,
120 |       connection_id: recommendation.connectionId,
121 |       diagnosis_id: recommendation.diagnosisId,
122 |     });
123 |     return toExperiment(data);
124 |   },
125 | 
126 |   approve: async (id: string, notes?: string): Promise<Experiment> => {
127 |     await apiClient.post(`/recommendations/${id}/approve`, { action: 'APPROVE', reason: notes });
128 |     await apiClient.post(`/experiments/${id}/deploy`);
129 |     const data = await apiClient.get<BackendExperiment>(`/experiments/${id}`);
130 |     return toExperiment(data);
131 |   },
132 | 
133 |   reject: async (id: string, reason?: string): Promise<Experiment> => {
134 |     await apiClient.post(`/recommendations/${id}/reject`, { action: 'REJECT', reason });
135 |     const data = await apiClient.get<BackendExperiment>(`/experiments/${id}`);
136 |     return toExperiment(data);
137 |   },
138 | };

