 1 | import { API_BASE_URL } from './client';
 2 | 
 3 | export interface SseSubscriptionOptions<T> {
 4 |   endpoint: string;
 5 |   onMessage: (data: T) => void;
 6 |   onError?: (error: Event) => void;
 7 |   onOpen?: () => void;
 8 | }
 9 | 
10 | export function subscribeToSse<T>({
11 |   endpoint,
12 |   onMessage,
13 |   onError,
14 |   onOpen,
15 | }: SseSubscriptionOptions<T>): () => void {
16 |   const url = endpoint.startsWith('http')
17 |     ? endpoint
18 |     : `${API_BASE_URL}${endpoint.startsWith('/') ? endpoint : `/${endpoint}`}`;
19 | 
20 |   if (typeof window === 'undefined' || typeof EventSource === 'undefined') {
21 |     return () => {};
22 |   }
23 | 
24 |   const eventSource = new EventSource(url, { withCredentials: true });
25 | 
26 |   eventSource.onopen = () => {
27 |     onOpen?.();
28 |   };
29 | 
30 |   const handleMessage = (event: MessageEvent) => {
31 |     try {
32 |       const parsed = JSON.parse(event.data) as T;
33 |       onMessage(parsed);
34 |     } catch {
35 |       onMessage(event.data as unknown as T);
36 |     }
37 |   };
38 |   eventSource.onmessage = handleMessage;
39 |   eventSource.addEventListener('canary_metric', handleMessage as EventListener);
40 |   eventSource.addEventListener('canary_completed', handleMessage as EventListener);
41 | 
42 |   eventSource.onerror = (err) => {
43 |     onError?.(err);
44 |   };
45 | 
46 |   return () => {
47 |     eventSource.close();
48 |   };
49 | }

