 1 | export function relativeTime(iso: string): string {
 2 |   const timestamp = new Date(iso).getTime()
 3 |   if (!Number.isFinite(timestamp)) return 'unknown'
 4 | 
 5 |   const diff = Math.max(0, Date.now() - timestamp)
 6 |   const s = Math.round(diff / 1000)
 7 |   if (s < 60) return `${s}s ago`
 8 |   const m = Math.round(s / 60)
 9 |   if (m < 60) return `${m}m ago`
10 |   const h = Math.round(m / 60)
11 |   if (h < 24) return `${h}h ago`
12 |   const d = Math.round(h / 24)
13 |   return `${d}d ago`
14 | }
15 | 
16 | export function absoluteTime(iso: string): string {
17 |   return new Date(iso).toLocaleString('en-US', {
18 |     month: 'short',
19 |     day: 'numeric',
20 |     hour: '2-digit',
21 |     minute: '2-digit',
22 |     hour12: false,
23 |     timeZone: 'UTC',
24 |   })
25 | }
