39 | export function deltaPct(baseline: number, candidate: number, betterWhenLower: boolean): {
40 |   label: string
41 |   improved: boolean
42 | } {
43 |   if (baseline === 0) return { label: '—', improved: false }
44 |   const change = ((candidate - baseline) / baseline) * 100
45 |   const improved = betterWhenLower ? change < 0 : change > 0
46 |   const sign = change > 0 ? '+' : ''
47 |   return { label: `${sign}${change.toFixed(1)}%`, improved }
48 | }

