17 | function spark(base: number, jitter: number, n = 24, drift = 0): number[] {
18 |     const out: number[] = []
19 |     let seed = base
20 |     for (let i = 0; i < n; i++) {
21 |         seed += (Math.sin(i * 1.3) + Math.cos(i * 0.7)) * jitter * 0.4 + drift
22 |         out.push(Math.max(0.1, Math.round((seed + (i % 3) * jitter * 0.15) * 100) / 100))
23 |     }
24 |     return out
25 | }

