690 | function forecastCurve(peak: number, crossDay: number): Forecast['curve'] {
691 |     const out: Forecast['curve'] = []
692 |     for (let d = 0; d <= 14; d++) {
693 |         const p = Math.min(peak, 0.04 + (peak - 0.04) * (1 - Math.exp(-d / (crossDay * 0.9))))
694 |         const band = 0.06 + d * 0.006
695 |         out.push({
696 |             day: d,
697 |             probability: Math.round(p * 1000) / 1000,
698 |             lower: Math.round(Math.max(0, p - band) * 1000) / 1000,
699 |             upper: Math.round(Math.min(1, p + band) * 1000) / 1000,
700 |         })
701 |     }
702 |     return out
703 | }

